package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.node.ObjectNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.persistence.mapper.*;import com.ruoyi.medical.persistence.mapper.BusinessAuditMapper.*;
import java.util.*;import java.math.BigInteger;import java.time.ZoneOffset;
import org.springframework.stereotype.Component;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
/** Sole supported adapter: actual DC-02 save receipt and real fixed-version current source authority. */
@Component
@ConditionalOnProperty(prefix="medical.business-audit",name="enabled",havingValue="true")
public final class BusinessAuditDocumentSavedAuthority{
 static final String ACTION="document.revision.saved",PURPOSE="AUDIT_READ";
 private final BusinessAuditMapper mapper;private final ResourceReadAuthority resources;private final DocumentReadService documents;private final PermissionSchema json;private final BusinessAuditPolicy policy;private final BusinessAuditSchema schema;private final SchemaCatalogue catalogue=SchemaCatalogue.fromClasspath();
 static final class Proof{private final Candidate row;private final DocumentReadService.MetadataRead metadata;private final ObjectNode entry;private Proof(Candidate row,DocumentReadService.MetadataRead metadata,ObjectNode entry){this.row=row;this.metadata=metadata;this.entry=entry;}ObjectNode entry(){return entry.deepCopy();}}
 public BusinessAuditDocumentSavedAuthority(BusinessAuditMapper mapper,ResourceReadAuthority resources,DocumentReadService documents,PermissionSchema json,BusinessAuditPolicy policy)throws Exception{this.mapper=mapper;this.resources=resources;this.documents=documents;this.json=json;this.policy=policy;schema=new BusinessAuditSchema();}
 Proof read(EnterpriseAccess.Admission a,String context,Candidate row)throws Exception{
  same(a.context().tenant_id(),row.tenantId());WireValues.uuid(row.auditId());if(row.projectId()==null)bad();grant(a,row);
  same(ACTION,row.action());same("SUCCESS",row.result());if(row.reasonCode()!=null)bad();same("1.0.0",row.schemaVersion());same(json.manifestSha256(),row.schemaManifest());same(row.subjectId(),row.createdBy());same(row.requestId(),row.traceId());WireValues.uuid(row.subjectId());WireValues.uuid(row.requestId());if(row.createdAt()==null)bad();bounded(row.payloadBytes());
  var v=values(a,row);var event=schema.validate("SavedEvent",schema.read(one(mapper.payload(v)),policy.maximumPayloadBytes()));if(event.required("reason").textValue().isBlank())bad();
  String document=event.required("document_id").textValue(),revision=event.required("document_revision").textValue();v.put("documentId",document);v.put("documentRevision",revision);v.put("operationId",event.required("operation_id").textValue());
  var op=one(mapper.operation(v));same(event.required("operation_id").textValue(),op.operationId());same("DC-02",op.operationName());same("COMPLETED",op.state());same(Integer.valueOf(201),op.httpStatus());if(op.errorCode()!=null)bad();same(document,op.targetId());same(row.subjectId(),op.subjectId());same(row.createdBy(),op.createdBy());same(row.classification(),op.classification());same("1.0.0",op.schemaVersion());same(row.schemaManifest(),op.schemaManifest());if(op.createdAt()==null||op.createdAt().isAfter(row.createdAt()))bad();bounded(op.responseBytes());
  var response=schema.read(one(mapper.operationResponse(v)),policy.maximumPayloadBytes());catalogue.validate("interfaces",response,"Envelope");var snapshot=response.required("data");catalogue.validate("interfaces",snapshot,"DocumentSnapshot");same(row.requestId(),response.required("request_id").textValue());same(event.required("revision"),response.required("resource_revision"));same(event.required("revision"),snapshot.required("revision"));same(document,snapshot.required("document_id").textValue());same(revision,snapshot.required("document_revision").textValue());same(row.projectId(),snapshot.required("project_id").textValue());same(event.required("body_sha256"),snapshot.at("/body/sha256"));
  for(String name:List.of("check_ids","review_ids","signature_ids","invalidation_reasons","stream_cursors"))if(!snapshot.required(name).isArray()||!snapshot.required(name).isEmpty())bad();same("0",snapshot.required("evidence_watermark").textValue());same(json.tree(List.of("document.edit")),snapshot.required("allowed_actions"));
  var target=one(mapper.target(v));same(row.projectId(),target.revisionProjectId());same(row.projectId(),target.metadataProjectId());same(row.projectId(),target.versionProjectId());same(row.projectId(),target.ownerProjectId());same(document,target.revisionDocumentId());same(document,target.metadataDocumentId());same(document,target.ownerDocumentId());same(revision,target.documentRevision());same(revision,target.metadataRevision());same(revision,target.versionId());same("DOCUMENT_REVISION",target.versionKind());same(target.revisionSnapshotId(),target.metadataSnapshotId());same(event.required("base_revision").textValue(),target.basedOnRevision());
  String body=event.required("body_sha256").textValue();same(body,target.revisionBodySha256());same(body,target.metadataBodySha256());same(body,target.metadataContentSha256());same(body,target.versionContentSha256());same(row.createdBy(),target.createdBy());same(row.classification(),target.classification());if(target.createdAt()==null||target.createdAt().isAfter(row.createdAt()))bad();
  var previous=WireValues.revision(event.required("revision").textValue()).subtract(BigInteger.ONE);if(previous.signum()<0)bad();var input=new InterfaceProtocol.RevisionInput(event.required("base_revision").textValue(),previous.toString(),snapshot.at("/body/artifact_id").textValue(),body,snapshot.required("body_schema_revision").textValue(),event.required("reason").textValue());
  same(op.requestSha256(),schema.hash(Map.of("method","POST","path","/api/documents/"+document+"/revisions","schema_version","1.0.0","schema_sha256",catalogue.schemaDigest("interfaces"),"body",input)));
  var metadata=documents.authorizeMetadata(a,context,document,revision);var header=metadata.header();same(row.tenantId(),header.tenantId());same(row.projectId(),header.projectId());same(document,header.documentId());same(revision,header.documentRevision());same(body,header.bodySha256());same(snapshot.at("/body/artifact_id").textValue(),header.bodyArtifactId());same(snapshot.required("body_schema_revision").textValue(),header.bodySchemaRevision());same(snapshot.required("template_version").textValue(),header.templateVersion());same(snapshot.required("plan_revision").textValue(),header.planRevision());same(target.createdAt(),header.createdAt());same(target.createdBy(),header.createdBy());
  same(snapshot.required("body"),json.tree(metadata.artifactReference("DOCUMENT_BODY")));same(snapshot.required("fields"),json.tree(metadata.artifactReference("DOCUMENT_FIELDS")));same(snapshot.required("evidence_links"),json.tree(metadata.artifactReference("DOCUMENT_EVIDENCE")));
  var entry=json.object().put("audit_id",row.auditId()).put("action",ACTION).put("occurred_at",row.createdAt().toInstant(ZoneOffset.UTC).toString()).put("actor_id",row.subjectId()).put("outcome",row.result());entry.set("target",json.object().put("resource_kind","DOCUMENT").put("project_id",row.projectId()).put("document_id",document).put("document_revision",revision).put("read_url","/api/documents/"+document+"/revisions/"+revision));return new Proof(row,metadata,entry);
 }
 void requireCurrent(EnterpriseAccess.Admission a,Proof proof)throws Exception{grant(a,proof.row);documents.requireMetadataCurrent(a,proof.metadata);}
 private void grant(EnterpriseAccess.Admission a,Candidate row)throws Exception{resources.require(a,new PermissionProtocol.Scope(a.context().tenant_id(),row.projectId(),"AUDIT",row.auditId()),"audit.read",PURPOSE);}
 private Map<String,Object> values(EnterpriseAccess.Admission a,Candidate row){var v=new HashMap<String,Object>();v.put("userId",a.actorId());v.put("projectId",row.projectId());v.put("auditId",row.auditId());v.put("maximumPayloadBytes",policy.maximumPayloadBytes());return v;}
 private void bounded(BigInteger count){if(count==null||count.signum()<1)bad();if(count.compareTo(BigInteger.valueOf(policy.maximumPayloadBytes()))>0)throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);}

 private static<T>T one(List<T> rows){if(rows.size()!=1||rows.get(0)==null)bad();return rows.get(0);}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
